import type { ReactNode } from "react";

import type { IconName } from "./types";

/*
 * The 21 glyphs, transcribed verbatim from `design-system/icons/*.svg`.
 *
 * Attribute names are camel-cased for JSX; every path `d` string is copied
 * byte-for-byte. Nothing was re-drawn, rounded or re-projected onto a common
 * viewBox - at these scales (the Polygon badge is drawn on 10x10) coordinate
 * rounding visibly shifts the circular coin marks and the flag roundel
 * off-centre. Each glyph keeps its own intrinsic viewBox and `Icon` normalises
 * at render time.
 *
 * WHY A TYPED MODULE AND NOT SVGR
 * The project builds with webpack for `next build` and turbopack for
 * `next dev`. An SVG loader would have to be configured twice in a
 * `next.config.ts` that Phase 0 froze, and a mismatch between the two would
 * only surface at deploy. This works identically in both and tree-shakes.
 *
 * NO GLYPH EMITS A DOM `id`. THIS IS A HARD RULE - DO NOT ADD ONE.
 * `id` is document-scoped, and a glyph is a value that renders as many times as
 * a page asks for it: `share-instagram` and `share-tiktok` render twice on
 * every `/blog/[slug]` (ShareRow appears in the article header AND its footer),
 * `flag-ng` twice on `/products/cross-border-payments`. Figma's exporter emits
 * `<defs>` with per-file ids like `clip0_1_3`, and icons.md S6 namespaced them
 * per glyph - which makes them unique per GLYPH, not per INSTANCE, so the
 * second render duplicated all nine of them. Invalid HTML, and axe's
 * duplicate-id rule fires.
 *
 * A per-instance prefix is the usual answer and is not available here: it needs
 * `useId()`, `useId()` is a hook, and `Icon` must stay renderable from a Server
 * Component (see the note in ./index.tsx - it is also why the accessible name
 * is an `aria-label` and not `aria-labelledby` + `<title id>`). So the ids are
 * gone instead, three ways, none of which changes a single painted pixel:
 *
 *   1. FOUR CLIPS WERE NO-OPS. `crypto-bnb`, `crypto-polygon`, `crypto-usdt`
 *      and `flag-ng`'s inner clip each clipped to a rect that the artwork is
 *      already inside (or exactly tangent to). Deleted outright.
 *
 *   2. THREE CLIPS WERE `<rect width=W height=W rx=W/2>` - i.e. the circle
 *      inscribed in the full viewBox (`share-instagram`, `share-tiktok`,
 *      `flag-ng`). That is `border-radius: 50%` on the root `<svg>`, exactly,
 *      at every size: the element box maps 1:1 onto the viewBox. Expressed as
 *      `clip: "circle"` below and applied by `Icon`.
 *
 *   3. GRADIENTS CANNOT EXIST WITHOUT AN id - `fill="url(#...)"` is the only
 *      way to reference one. `share-instagram`'s two radial gradients are
 *      therefore moved into a data-URI `<image>`, which is a separate SVG
 *      document with its own id scope, so its ids can never collide with the
 *      host page's however many times the glyph renders. The markup inside it
 *      is the original export, verbatim.
 *
 * A glyph that needs a NEW gradient follows (3). A glyph that needs a NEW clip
 * that is not a circle has no id-free form - say so rather than reintroducing
 * one.
 *
 * COLOUR - AND THE ONLY SANCTIONED RAW HEX IN THE CODEBASE
 * The 13 single-colour glyphs are authored `fill="currentColor"` and inherit
 * from their text context. The fixed-fill glyphs keep their fills verbatim,
 * because components.md S4.5 requires it: they are exchange-recognised brand
 * marks, a national flag and the Azza logo. Recolouring one is a correctness
 * bug, not a theming choice, and `Icon` deliberately offers no way to try.
 *
 * The complete list, so an auditor can confirm none of these is drift:
 *
 *   crypto-bnb        #E3BE61   Binance gold
 *   crypto-polygon    #6F41D8   Polygon purple
 *   crypto-usdt       #26A17B   Tether green
 *   flag-ng           #50AF95   backing rect (dead paint, but it is the source
 *                               geometry for the circular clip - icons.md S6)
 *                     #008751   Nigerian flag green
 *   share-instagram   #FFDD55 #FF543E #C837AB #3771C8 #6600FF
 *                               the two-stop radial gradient
 *   logo-azza-mark    #3430E9   Azza brand blue
 *   logo-azza-wordmark #3430E9  Azza brand blue
 *   brand-x           black     X's logo block. The keyword, not #000000 - it
 *                               is what 765:367 exports.
 *   brand-instagram   #FFDD55 #FF543E #C837AB #3771C8 #6600FF
 *                               the same two gradients as `share-instagram`,
 *                               but on the SQUIRCLE badge, unclipped, and with
 *                               their own 16-unit gradientTransforms. Not
 *                               shareable with it - see BRAND_INSTAGRAM_BADGE.
 *                     white     the camera glyph
 *   brand-youtube     #FF0000   YouTube red
 *                     white     the play triangle
 *   wallet-filled     #A57DD9   Products dropdown hover, Crypto Wallet
 *   money-bag-filled  #6764EE   Products dropdown hover, Cross-Border Payments
 *   briefcase-filled  #76B94D   Products dropdown hover, Azza Business
 *
 * THE FIRST TWO OF THOSE THREE TRADED COLOURS on 2026-08-17 at the operator's
 * request - the wallet was #6764EE and the money bag #A57DD9. They read as
 * transposed against any older screenshot; they are not. Verified against
 * 775:329 / 775:331 the day of the swap.
 *
 * They were also missing from this list until then, added by an earlier pass
 * without being inventoried - which is exactly the drift the list exists to
 * catch. The two Socials filled marks (`social-instagram-filled` #FF0069,
 * `social-youtube-filled` #FF4040) are still absent, and are NOT recorded here
 * because they were not re-checked against the file on that pass; inventory them
 * when someone next verifies 776:464 rather than transcribing them on trust.
 *
 * None of these has a token, and none should. For the third-party marks and the
 * flag, tokens.json carries the AZZA palette and not brand equity. The three
 * dropdown fills ARE ours, and are still not tokens for a different reason: the
 * design paints them onto the vector rather than styling the element, `Icon`
 * offers no way to recolour a fixed-fill glyph, and the hover accent has exactly
 * one consumer. `#3430E9` does exist as `--color-fg-brand`, but the two logos are
 * self-contained brand assets exported from 498:604 and are kept byte-identical
 * with the rest.
 */

export interface Glyph {
  /** Intrinsic viewBox, verbatim. Never rewritten to a common box. */
  viewBox: string;
  /** The glyph's own subtree. */
  body: ReactNode;
  /**
   * The export clipped this glyph to the circle inscribed in its viewBox.
   * `Icon` reproduces it with `rounded-full` on the root `<svg>` rather than a
   * `<clipPath id>` - see the id rule above. Only set this when the original
   * clip really was `<rect width=W height=W rx=W/2>` over the whole viewBox.
   */
  clip?: "circle";
}

/*
 * `share-instagram`'s badge - the squircle painted with two radial gradients,
 * then clipped to the circle. Reason (3) in the id rule above: a gradient must
 * be referenced by id, so it ships as its own SVG document inside a data URI,
 * where the ids `a`, `b` and `c` are scoped to that document and cannot
 * collide with the page.
 *
 * Everything here is the original 498:604 export unchanged - the same path
 * twice, the same two `<radialGradient>` transforms and stops, the same
 * `rx=12` clip. Only the id NAMES differ, and they are unreachable from
 * outside. The white camera glyph is NOT in here: it carries no id, so it
 * stays inline where it renders as part of the host document.
 */
const SHARE_INSTAGRAM_BADGE_PATH =
  "M18.375 0H5.625C2.5184 0 0 2.5184 0 5.625V18.375C0 21.4816 2.5184 24 5.625 24H18.375C21.4816 24 24 21.4816 24 18.375V5.625C24 2.5184 21.4816 0 18.375 0Z";

const SHARE_INSTAGRAM_BADGE_SVG =
  `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' width='24' height='24'>` +
  `<defs>` +
  `<radialGradient id='a' cx='0' cy='0' r='1' gradientUnits='userSpaceOnUse'` +
  ` gradientTransform='translate(6.375 25.8485) rotate(-90) scale(23.7858 22.1227)'>` +
  `<stop stop-color='#FFDD55'/>` +
  `<stop offset='0.1' stop-color='#FFDD55'/>` +
  `<stop offset='0.5' stop-color='#FF543E'/>` +
  `<stop offset='1' stop-color='#C837AB'/>` +
  `</radialGradient>` +
  `<radialGradient id='b' cx='0' cy='0' r='1' gradientUnits='userSpaceOnUse'` +
  ` gradientTransform='translate(-4.02009 1.72884) rotate(78.681) scale(10.6324 43.827)'>` +
  `<stop stop-color='#3771C8'/>` +
  `<stop offset='0.128' stop-color='#3771C8'/>` +
  `<stop offset='1' stop-color='#6600FF' stop-opacity='0'/>` +
  `</radialGradient>` +
  `<clipPath id='c'><rect width='24' height='24' rx='12'/></clipPath>` +
  `</defs>` +
  `<g clip-path='url(#c)'>` +
  `<path d='${SHARE_INSTAGRAM_BADGE_PATH}' fill='url(#a)'/>` +
  `<path d='${SHARE_INSTAGRAM_BADGE_PATH}' fill='url(#b)'/>` +
  `</g>` +
  `</svg>`;

/**
 * Percent-encoded, not base64: an auditor can read the markup above and the
 * encoding is a pure function of it, evaluated once at module load and
 * therefore identical on the server and in the browser.
 */
const SHARE_INSTAGRAM_BADGE_HREF = `data:image/svg+xml,${encodeURIComponent(
  SHARE_INSTAGRAM_BADGE_SVG,
)}`;

/*
 * `brand-instagram`'s badge - 765:375, the redesigned Socials row.
 *
 * WHY THIS IS NOT `SHARE_INSTAGRAM_BADGE_SVG` REUSED AT A SMALLER SIZE
 * The two are the same artwork at different scales and the difference is not
 * scale-invariant, so neither can serve for the other:
 *
 *   1. `share-instagram` is CLIPPED TO A CIRCLE (`rx=12` on 24) - it is a round
 *      avatar. This one is left as the SQUIRCLE the path already draws
 *      (rx=3.75 on 16), which is Instagram's actual app mark. Dropping the clip
 *      is the whole visual difference between them.
 *   2. A `gradientTransform` is in user space, so it does NOT follow a viewBox
 *      change. These translate/scale values are 16-unit; the other's are
 *      24-unit. Rendering either set in the other's box moves the gradient's
 *      focus off the artwork.
 *
 * Reason (3) in the id rule above still applies unchanged: the gradients need
 * ids, so they ship inside their own SVG document where `a` and `b` are scoped
 * to it. The ids are deliberately the SAME letters as the other badge's - two
 * separate documents, two separate scopes, no collision possible even when both
 * glyphs render on one page (which `/help` does).
 */
const BRAND_INSTAGRAM_BADGE_PATH =
  "M12.25 0H3.75C1.67893 0 0 1.67893 0 3.75V12.25C0 14.3211 1.67893 16 3.75 16H12.25C14.3211 16 16 14.3211 16 12.25V3.75C16 1.67893 14.3211 0 12.25 0Z";

const BRAND_INSTAGRAM_BADGE_SVG =
  `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16'>` +
  `<defs>` +
  `<radialGradient id='a' cx='0' cy='0' r='1' gradientUnits='userSpaceOnUse'` +
  ` gradientTransform='translate(4.25 17.2323) rotate(-90) scale(15.8572 14.7484)'>` +
  `<stop stop-color='#FFDD55'/>` +
  `<stop offset='0.1' stop-color='#FFDD55'/>` +
  `<stop offset='0.5' stop-color='#FF543E'/>` +
  `<stop offset='1' stop-color='#C837AB'/>` +
  `</radialGradient>` +
  `<radialGradient id='b' cx='0' cy='0' r='1' gradientUnits='userSpaceOnUse'` +
  ` gradientTransform='translate(-2.68005 1.1526) rotate(78.68) scale(7.08825 29.218)'>` +
  `<stop stop-color='#3771C8'/>` +
  `<stop offset='0.128' stop-color='#3771C8'/>` +
  `<stop offset='1' stop-color='#6600FF' stop-opacity='0'/>` +
  `</radialGradient>` +
  `</defs>` +
  `<path d='${BRAND_INSTAGRAM_BADGE_PATH}' fill='url(#a)'/>` +
  `<path d='${BRAND_INSTAGRAM_BADGE_PATH}' fill='url(#b)'/>` +
  `</svg>`;

const BRAND_INSTAGRAM_BADGE_HREF = `data:image/svg+xml,${encodeURIComponent(
  BRAND_INSTAGRAM_BADGE_SVG,
)}`;

